def choose_move(observation):
    def g(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return default

    def is_num(x):
        return isinstance(x, (int, float))

    def to_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [v[0], v[1]]
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("cx", "cy"), ("i", "j")):
                if a in v and b in v and is_num(v[a]) and is_num(v[b]):
                    return [v[a], v[b]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(d):
        if d > 1:
            return 1
        if d < -1:
            return -1
        return d

    def norm2(x, y):
        return x * x + y * y

    def flatten_positions(x):
        out = []
        if x is None:
            return out
        if isinstance(x, dict):
            for k in ("positions", "pos", "cells", "tiles", "targets", "resources", "enemies", "opponents", "players", "agents", "objects"):
                if k in x:
                    out.extend(flatten_positions(x.get(k)))
            p = to_pos(x)
            if p is not None:
                out.append(p)
            return out
        if isinstance(x, (list, tuple)):
            p = to_pos(x)
            if p is not None:
                out.append(p)
                return out
            for item in x:
                out.extend(flatten_positions(item))
        return out

    me = None
    for key in ("agent_pos", "position", "pos", "self_pos", "player_pos", "loc", "location", "self"):
        me = to_pos(g(observation, key))
        if me is not None:
            break
    if me is None:
        me = to_pos(g(observation, "agent"))
    if me is None:
        me = [0, 0]

    width = g(observation, "width", None)
    height = g(observation, "height", None)
    grid = g(observation, "grid", None)
    if (width is None or height is None) and isinstance(grid, (list, tuple)) and grid:
        height = len(grid)
        first = grid[0]
        if isinstance(first, (list, tuple)):
            width = len(first)

    # Collect likely targets / hazards from common fields
    resources = []
    for k in ("resources", "resource_positions", "resource_pos", "food", "targets", "treasures", "coins", "gems"):
        resources.extend(flatten_positions(g(observation, k)))

    enemies = []
    for k in ("enemies", "enemy_positions", "opponents", "opponent_positions", "adversaries", "threats"):
        enemies.extend(flatten_positions(g(observation, k)))

    allies = []
    for k in ("allies", "teammates", "friends"):
        allies.extend(flatten_positions(g(observation, k)))

    territory = []
    for k in ("territory", "frontier", "boundary", "unclaimed", "neutral"):
        territory.extend(flatten_positions(g(observation, k)))

    # Sometimes objects are embedded in a generic list
    objs = flatten_positions(g(observation, "objects"))
    if not resources:
        resources = objs[:]
    if not enemies:
        enemies = flatten_positions(g(observation, "agents"))
        enemies.extend(flatten_positions(g(observation, "players")))

    # Mode hint
    mode = str(g(observation, "mode", "")).lower()
    if not mode:
        mode = str(g(observation, "task", "")).lower()
    if not mode:
        mode = str(g(observation, "game", "")).lower()

    candidates = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def best_dist(points, x, y):
        if not points:
            return None
        d = None
        for p in points:
            dd = abs(p[0] - x) + abs(p[1] - y)
            if d is None or dd < d:
                d = dd
        return d

    best = None
    best_score = None

    for dx, dy in candidates:
        nx, ny = me[0] + dx, me[1] + dy

        score = 0.0

        # Prefer remaining inside known bounds
        if width is not None and nx is not None:
            if nx < 0 or nx >= width:
                score -= 50
        if height is not None and ny is not None:
            if ny < 0 or ny >= height:
                score -= 50

        # Resource collection / general seeking
        if resources:
            d0 = best_dist(resources, me[0], me[1])
            d1 = best_dist(resources, nx, ny)
            if d0 is not None and d1 is not None:
                score += (d0 - d1) * 6.0

        # Territory control: move toward frontier / unclaimed / neutral
        if territory:
            d0 = best_dist(territory, me[0], me[1])
            d1 = best_dist(territory, nx, ny)
            if d0 is not None and d1 is not None:
                score += (d0 - d1) * 4.0

        # Pursuit / evasion: avoid enemies if close, otherwise approach if mode suggests chase
        if enemies:
            d0 = best_dist(enemies, me[0], me[1])
            d1 = best_dist(enemies, nx, ny)
            if d0 is not None and d1 is not None:
                if "pursuit" in mode or "chase" in mode or "attack" in mode:
                    score += (d0 - d1) * 3.5
                else:
                    if d0 <= 3:
                        score += (d1 - d0) * 8.0
                    else:
                        score += (d0 - d1) * 1.0

        # Mild center bias when nothing else is known
        if width is not None and height is not None:
            cx = (width - 1) / 2.0
            cy = (height - 1) / 2.0
            score -= (norm2(nx - cx, ny - cy) - norm2(me[0] - cx, me[1] - cy)) * 0.01

        # Small preference for movement over standing still when useful
        if dx == 0 and dy == 0:
            score -= 0.05

        if best_score is None or score > best_score:
            best_score = score
            best = [dx, dy]

    if best is None:
        return [0, 0]
    return [clamp_step(best[0]), clamp_step(best[1])]

